    "description": "据新疆日报，8月22日，在昆仑健源（新疆）生物科技有限责任公司（简称“昆仑健源”）生产车间，一筐红枣被倒入清洗池。经过酶解、提取、膜分离、纯化、浓缩、冻干等工序，24小时后，这批红枣变成淡黄色糖肽冻干粉或液体原料。当日，新疆特色生物糖肽生产线正式投产，这意味着国内最大糖肽产业化生产基地落地新疆。该项目由昆仑健源联合中国科学院烟台海岸带研究所等13家高校院所7年协同攻关，累计投入超1亿元，搭建起“研发—中试—量产—展示”完整产业闭环。（人…",
    "content": "据新疆日报，8月22日，在昆仑健源（新疆）生物科技有限责任公司（简称“昆仑健源”）生产车间，一筐红枣被倒入清洗池。经过酶解、提取、膜分离、纯化、浓缩、冻干等工序，24小时后，这批红枣变成淡黄色糖肽冻干粉或液体原料。当日，新疆特色生物糖肽生产线正式投产，这意味着国内最大糖肽产业化生产基地落地新疆。该项目由昆仑健源联合中国科学院烟台海岸带研究所等13家高校院所7年协同攻关，累计投入超1亿元，搭建起“研发—中试—量产—展示”完整产业闭环。（人民财讯）"
