    "description": "中新社香港8月23日电 香港特区政府财政司司长陈茂波23日发表网志表示，去年12月至今年5月，香港与AI(人工智能)相关的新股集资额近1000亿元(港元，下同)，约占同期新股集资额的55%，反映出国家在AI方面的迅速发展，对香港经济和金融市场发挥了显著助力。",
    "content": "中新社香港8月23日电 香港特区政府财政司司长陈茂波23日发表网志表示，去年12月至今年5月，香港与AI(人工智能)相关的新股集资额近1000亿元(港元，下同)，约占同期新股集资额的55%，反映出国家在AI方面的迅速发展，对香港经济和金融市场发挥了显著助力。"
