    "title": "13条河流19个水文站超警 广西升级发布洪水红色预警",
    "link": "https://www.chinanews.com.cn/gn/2026/08-23/10682626.shtml",
    "pub_date": "2026-08-23 12:48:11",
    "author": "",
    "description": "中新网南宁8月23日电 (陈秋霞 周也茹) 广西壮族自治区水文中心23日提供的信息显示，8月22日8时至23日8时，受强降雨影响，左江及支流明江、黑水河等江河出现4至11米的涨水过程，其中明江及支流公安河、派连河、思州河，左江及上游平而河、支流凭祥河，北仑河等13条河流19个水文站出现超警0.03至6.03米的洪水。",
