    "pub_date": "2026-08-23 12:07:49",
    "author": "邢拓",
    "description": "中埃合拍纪录片《海丝双城记》日前在京发布。这部纪录片历时2年完成拍摄制作，以当代中埃民间交流与合作为主题，讲述了“一带一路”倡议下中埃文明对话的真实故事。 2026年是中埃建交70周年，这部纪录片以中国泉州与埃及亚历山大港两座千年海丝名城为坐标，记录中埃两国在商贸、文化、教育等领域的民间交往故事。片中人物涵盖经商创业者、旅游业者、跨国家庭、制香传人、考古工作者，以“民间使者”视角呈现中埃文明互鉴的鲜活样本。 业内专家表示，《海丝双城记》…",
    "content": "中埃合拍纪录片《海丝双城记》日前在京发布。这部纪录片历时2年完成拍摄制作，以当代中埃民间交流与合作为主题，讲述了“一带一路”倡议下中埃文明对话的真实故事。 2026年是中埃建交70周年，这部纪录片以中国泉州与埃及亚历山大港两座千年海丝名城为坐标，记录中埃两国在商贸、文化、教育等领域的民间交往故事。片中人物涵盖经商创业者、旅游业者、跨国家庭、制香传人、考古工作者，以“民间使者”视角呈现中埃文明互鉴的鲜活样本。 业内专家表示，《海丝双城记》以海洋文化为依托，以海上丝绸之路的历史为线索，以真实故事和日常细节为载体，深入两…"
