    "description": "“处暑无三日，新凉直万金。”处暑节气到，这是秋季的第二个节气，此时暑气渐退，凉意初生，“渐有新凉递好秋”。 近日，游客在黄山风景区内登山。初秋时节，安徽省黄山市黄山风景区天气宜人，旅游热度不减。新华社记者 常能嘉 摄 《月令七十二候集解》中记载：“处暑，七月中。处，止也，暑气至此而止矣。”其中“处”意为“终止”，表示暑气至此消散。“离离暑云散，袅袅凉风起。”炎热的暑天快要结束，我们逐渐进入到气象意义上的秋天，白天热，早晚凉，昼夜温差增大…",
    "content": "“处暑无三日，新凉直万金。”处暑节气到，这是秋季的第二个节气，此时暑气渐退，凉意初生，“渐有新凉递好秋”。 近日，游客在黄山风景区内登山。初秋时节，安徽省黄山市黄山风景区天气宜人，旅游热度不减。新华社记者 常能嘉 摄 《月令七十二候集解》中记载：“处暑，七月中。处，止也，暑气至此而止矣。”其中“处”意为“终止”，表示暑气至此消散。“离离暑云散，袅袅凉风起。”炎热的暑天快要结束，我们逐渐进入到气象意义上的秋天，白天热，早晚凉，昼夜温差增大。不过，民谚说“处暑天还暑，好似秋老虎”，我国不少地区，尤其是南方地区，“秋老虎…"
