    "author": "叶日者",
    "description": "《欢迎来龙餐馆》剧照 近日，电影《欢迎来龙餐馆》全国热映，口碑和票房持续走高。这部由文牧野执导、沈腾主演的现实题材影片，把一间中餐馆置于中东战火之下，以一餐一饭为线索，串起普通人在动荡中的谋生、离散与相守，道出中国人对和平的朴素理解与热切向往。 影片讲述中国厨师徐福远赴异国谋生，在战乱中，与龙餐馆的一众伙伴守护孤儿、彼此扶持的故事。枪声、炮火和逃亡构成了故事沉重的反战底色，但全片反复回响的，却是一句中国人再熟悉不过的叮嘱：“好好吃饭。”…",
