    "content": "五星级酒店饭局、身家数亿的老总、稳赚不赔的生意……这些元素组合在一起，你以为是商界传奇，其实是一场精心编排的“大戏”。 近日，记者从上海市公安局松江分局获悉一起离奇诈骗案：一老板半年内被骗走1400多万元，9名嫌疑人中6名是专业演员。有人演“外国买家”，有人演“集团高管”，还有人演“手眼通天的社会姐”。剧本是假的，身份是假的，连桌上成捆的“现金”也多是练功券。唯一真实的，只有钱老板转出去的真金白银。 精心设局：从一张假汇票开始 钱老板在松江经营钢铁批发生意，偶尔也做银行承兑汇票贴现业务。2025年12月，认识十来年…"
