    "title": "“嬢嬢秀”为乡村文旅消费注入新活力",
    "link": "http://www.news.cn/20260823/f669ee8d76d44f89a1ddcb0265ad9b42/c.html",
    "pub_date": "2026-08-23 11:14:31",
    "author": "李爱斌",
    "description": "本周，一场以乡村“嬢嬢”为主角的文体秀，在武陵山间的重庆市酉阳土家族苗族自治县大溪镇热闹举行。 平日里的家庭主妇、种田能手，亦或是含饴弄孙的“老嬢嬢”，相约走进篮球场、走上T台，展示属于她们的风采。 这场为期三天的乡村“嬢嬢秀”，不仅丰富了当地群众的精神文化生活，也让大溪及周边乡镇的乡村夜间经济、民俗集市消费持续升温，为乡村文旅产业注入新活力。 作者：李爱斌、段成军、石嘉黎 新华社音视频部制作",
