    "content": "新华社达累斯萨拉姆8月22日电（记者华洪立 林光耀）由中国电建集团和中国东方电气集团参与建设的坦桑尼亚朱利叶斯·尼雷尔水电站22日正式投入使用。 坦桑尼亚总统哈桑出席投运仪式并宣布电站正式投入运营。哈桑说，该水电站目前能提供的电力约占坦全国电力供应总量的一半，新增发电能力将有效缓解长期困扰坦桑尼亚的电力短缺问题。充足稳定的电力将为坦桑尼亚创造更多商业投资和工业发展机遇，带动就业增长，提高居民收入，并进一步增强国家经济发展活力。 中国电建该项目经理张睿介绍，中国电建承担了主坝、消力池、引水系统、导流洞、金属结构等主体…"
