    "content": "新华社哈尔滨8月23日电（记者董宝森、黄腾）黑龙江省水文水资源中心23日发布乌苏里江干流海青站江段洪水黄色预警，提示沿江地区相关部门做好防范应对工作。 受上游干支流来水影响，乌苏里江干流海青站水位持续上涨，8月23日8时海青站水位40.12米，与警戒水位（40.12米）持平，达到洪水黄色预警发布标准。根据《黑龙江省主要江河洪水预警发布管理办法》规定，黑龙江省水文水资源中心8月23日8时升级发布黑龙江省佳木斯市乌苏里江干流海青站江段洪水黄色预警。 黑龙江省水文水资源中心提示沿江地区相关部门做好防范应对工作，加强巡堤查…"
