    "content": "新华社德国杜塞尔多夫8月22日电（记者赵建通）2026-2027赛季德国乒乓球甲级联赛22日进行第二轮较量，中国名将樊振东迎来加盟杜塞尔多夫俱乐部后的正式比赛首秀。他两次出场均取胜，帮助球队主场3:1击败巴特柯尼希斯霍芬队。 当天比赛在杜塞尔多夫三菱电机体育馆举行，超过3500名观众到场。首盘比赛，樊振东对阵20岁的德国球员贝塔斯迈尔。首局樊振东以9:11告负，随后他逐渐掌控比赛，以11:5、11:8和11:9连扳三局，为主队拿下第一分。 随后，杜塞尔多夫队的贾哈以1:3不敌泽利科，两队大比分战成1:1。第三盘，德…"
