    "content": "新华社太原8月23日电（记者邓浩然）站在地头，手里搓着饱满的籽粒，细看成熟度，杜芝青打量着眼前这片即将成熟的庄稼，盘算着今年的收成。丰收在望，他总算是放了心。作为本地的种粮大户，杜芝青和这漂洋过海而来的植物打交道，已经是第六个年头了。 在这片位于山西忻州静乐县的庄稼地上，高大的植株像个扫把，花穗又像高粱穗，红色、紫色、黄色，颜色不一，整齐分布在眼前这片谷地里。在素有“小杂粮王国”之称的山西忻州，这样的“洋庄稼”，也是稀罕事。 眼前这片色彩斑斓的庄稼地，见证着一粒“洋种子”扎根黄土高原的完整蜕变。 位于山西省忻州市静…"
