    "content": "8月22日，亚太经济合作组织（APEC）2026年第三次高官会及相关会议的部分与会代表在大连参观辽渔集团科技馆。新华社记者 李钢 摄 新华社大连8月23日电（记者崔师豪、武江民）当一辆电动汽车驶入陌生城市，充电接口能否匹配、付款是否方便、补能是否安全，直接影响用户对绿色出行的信心。 近日，在辽宁大连，来自多个APEC经济体的政府、企业和技术机构代表展开讨论：如何通过标准协同，让电动汽车在不同市场“充得上、充得快、充得安心”。 据国际能源署统计，2025年全球电动汽车销量超过2000万辆，同比增长20%，约占新车销量…"
