    "content": "自营产品收入由35.23亿元增至48.39亿元，同比增长37.4%，占总收入约85%。 除了自营产品及直播电商业务增长，健康及营养产品贡献增加也是毛利率提升的原因。 东方甄选已由2025年12月的二十余位主播，发展至目前八十余人的主播和上播团队，计划在2026年底扩充至100人以上。 南方周末记者 贾梦雅 责任编辑：冯叶 2026年7月18日，陕西省西安市，东方甄选西北线下首店。视觉中国/图 “过去大半年，整个团队真的是急行军的状态。”2026年8月21日晚，在东方甄选2026财年业绩交流会上，孙进形容道。 孙进于…"
