    "description": "据媒体援引知情人士透露，多家“英伟达最大客户”已被告知，由于内存芯片成本飙升，搭载英伟达人工智能芯片的服务器价格将会上涨，很多情况下涨幅将超过15%。这一轮涨价将适用于明年年初出货的系统，包括搭载Vera Rubin和Grace Blackwell芯片组合的服务器。具体涨幅将取决于使用的英伟达芯片，以及服务器采用的内存配置。（财联社）",
    "content": "据媒体援引知情人士透露，多家“英伟达最大客户”已被告知，由于内存芯片成本飙升，搭载英伟达人工智能芯片的服务器价格将会上涨，很多情况下涨幅将超过15%。这一轮涨价将适用于明年年初出货的系统，包括搭载Vera Rubin和Grace Blackwell芯片组合的服务器。具体涨幅将取决于使用的英伟达芯片，以及服务器采用的内存配置。（财联社）"
