    "content": "2026年08月23日 现代化产业体系是现代化国家的物质技术基础，也是中国经济应对风浪、赢得未来的底气所在。 今年前7月，全国规模以上工业增加值同比增长5.3%。据国家统计局初步测算，前7月，新动能对规模以上工业增长的贡献率为50.9%。 7月30日，习近平总书记主持中共中央政治局会议。会议强调：“加快现代化产业体系建设，加强对基础研究的长期稳定支持，深入实施‘人工智能+’行动，发展智能经济新形态，完善人工智能治理体系。积极推动前沿技术突破和未来产业发展，着力打造新兴支柱产业，持续推动传统产业改造升级。” “十五五…"
