    "description": "2026年08月23日 中小学校园里，学习人工智能校本课程；大学里，修读人工智能公共基础课……如今，人工智能相关课程已进入许多学生的课程表。 《教育发展“十五五”规划》提出，“推进人工智能全学段教育，提升学生人工智能素养，增强提出问题、解决问题的能力。” 各学段的人工智能教育，学什么、怎么教、如何教好？记者进行了采访。 各学段 学什么 多地推出相关文件，明确课时要求 4月，教育部等5部门印发《“人工智能+教育”行动计划》（以下简称“行动…",
    "content": "2026年08月23日 中小学校园里，学习人工智能校本课程；大学里，修读人工智能公共基础课……如今，人工智能相关课程已进入许多学生的课程表。 《教育发展“十五五”规划》提出，“推进人工智能全学段教育，提升学生人工智能素养，增强提出问题、解决问题的能力。” 各学段的人工智能教育，学什么、怎么教、如何教好？记者进行了采访。 各学段&nbsp;&nbsp;学什么 多地推出相关文件，明确课时要求 4月，教育部等5部门印发《“人工智能+教育”行动计划》（以下简称“行动计划”），对推动人工智能人才培养与素养提升作出要求。教育部…"
