    "content": "2026年08月23日 8月18日，澳门特区政府正式发布《澳门特别行政区经济和社会发展第三个五年规划（2026—2030年）》。这是澳门特区贯彻落实习近平主席重要指示精神，主动对接国家“十五五”规划的重大举措，是具有澳门特色“一国两制”成功实践迈出的又一重要步伐，对于推动澳门融入和服务国家发展大局、实现澳门高质量发展具有“一规引未来”的里程碑意义。 “十五五”规划纲要指出，坚定不移贯彻“一国两制”、“港人治港”、“澳人治澳”、高度自治方针，落实“爱国者治港”、“爱国者治澳”原则，提升港澳依法治理效能，促进港澳经济社…"
