    "description": "2026年08月23日 我出生在黑龙江的小兴安岭脚下一座叫伊春的城市。那是一个寒冷的冬天。我第一眼看到的世界应该就是寒冬、白雪和呼啸的北风。这种刻骨铭心的凛冽，深入骨髓。我不喜欢造作、虚假、刻意和雕琢。我喜欢粗粝、天然、朴素和浑然天成的力量感。童年、少年、青年……我一生中最重要的时光都在这里度过。年轻的时候，人在各种欲望和纷杂混乱的情绪下，内心是粗糙和盲目的。人活到了一定岁数，慢慢安静下来，才会看到很多年轻时看不到的东西。随着年纪的增长…",
    "content": "2026年08月23日 我出生在黑龙江的小兴安岭脚下一座叫伊春的城市。那是一个寒冷的冬天。我第一眼看到的世界应该就是寒冬、白雪和呼啸的北风。这种刻骨铭心的凛冽，深入骨髓。我不喜欢造作、虚假、刻意和雕琢。我喜欢粗粝、天然、朴素和浑然天成的力量感。童年、少年、青年……我一生中最重要的时光都在这里度过。年轻的时候，人在各种欲望和纷杂混乱的情绪下，内心是粗糙和盲目的。人活到了一定岁数，慢慢安静下来，才会看到很多年轻时看不到的东西。随着年纪的增长，我渐渐对这块土地上发生过的事越来越有兴趣。查阅历史，看纪录片，搜集地方志，一度…"
