    "description": "2026年08月23日 夜幕降临，灯光亮起。在海南五指山市南圣河上，一场别开生面的“村秀”拉开帷幕，藏在雨林中的小城也沸腾了起来。 穿的是民族服装，拿的是农耕器具、当地特产，村里的阿婆阿叔成了模特，赤脚走着台步，扬起水花。停下脚步，“模特们”定点却不转身，借着立麦大声亮相，“这是我们村产的水稻，欢迎大家来看、来尝！”朴素的乡音激起阵阵欢呼与掌声。 “在我们这，干完农活就走秀！”看定点，摆造型，村民王堂健话里带着自豪。从2023年首季“村…",
    "content": "2026年08月23日 夜幕降临，灯光亮起。在海南五指山市南圣河上，一场别开生面的“村秀”拉开帷幕，藏在雨林中的小城也沸腾了起来。 穿的是民族服装，拿的是农耕器具、当地特产，村里的阿婆阿叔成了模特，赤脚走着台步，扬起水花。停下脚步，“模特们”定点却不转身，借着立麦大声亮相，“这是我们村产的水稻，欢迎大家来看、来尝！”朴素的乡音激起阵阵欢呼与掌声。 “在我们这，干完农活就走秀！”看定点，摆造型，村民王堂健话里带着自豪。从2023年首季“村秀”便开始参与排练的他，见证了这一农民秀场的新变化。从田间地头到碧波之上，从走秀…"
