    "title": "强风暴横扫波罗的海三国 致两人死亡",
    "link": "http://www.news.cn/20260823/f1967ce0486c4da3864dd899f2268e2d/c.html",
    "pub_date": "2026-08-23 07:29:04",
    "author": "陈玉芬",
    "description": "新华社里加8月23日电（记者陈玉芬）一个强气旋22日由南向北横扫波罗的海三国，给立陶宛、拉脱维亚和爱沙尼亚带来强风、暴雨和雷暴，造成大范围树木倒伏、建筑和电力设施受损以及城市积水。当地媒体和救援部门的最新消息显示，恶劣天气导致拉脱维亚和立陶宛各有一人死亡，另有数人受伤，数十万用户供电中断。 此次强气旋从南部进入拉脱维亚，同时带来暴雨和破坏性大风。拉脱维亚通讯社将其称为2005年1月以来破坏性最强风暴。拉脱维亚国家消防和救援局22日晚说，…",
    "content": "新华社里加8月23日电（记者陈玉芬）一个强气旋22日由南向北横扫波罗的海三国，给立陶宛、拉脱维亚和爱沙尼亚带来强风、暴雨和雷暴，造成大范围树木倒伏、建筑和电力设施受损以及城市积水。当地媒体和救援部门的最新消息显示，恶劣天气导致拉脱维亚和立陶宛各有一人死亡，另有数人受伤，数十万用户供电中断。 此次强气旋从南部进入拉脱维亚，同时带来暴雨和破坏性大风。拉脱维亚通讯社将其称为2005年1月以来破坏性最强风暴。拉脱维亚国家消防和救援局22日晚说，该国已确认此次风暴造成一人死亡、至少两人受伤。 拉脱维亚铁路运营部门说，由于天气…"
