    "description": "新华社布达佩斯8月22日电（记者陈浩）匈牙利总理毛焦尔·彼得22日宣布，得益于紧急工程施工作业及多瑙河水位回升，该国唯一的核电站——保克什核电站3号机组已于当天恢复发电。 毛焦尔当天在核电站现场表示，3号机组的6号汽轮机已重新联网恢复发电。本月早些时候，干旱引发的多瑙河极低水位严重限制冷却水吸入，导致部分机组被迫停运。 为保障冷却水供应，匈牙利政府日前实施紧急应对措施，开始建造水下潜坝，并在河道中有控制地沉入两艘80米长的驳船。毛焦尔表…",
    "content": "新华社布达佩斯8月22日电（记者陈浩）匈牙利总理毛焦尔·彼得22日宣布，得益于紧急工程施工作业及多瑙河水位回升，该国唯一的核电站——保克什核电站3号机组已于当天恢复发电。 毛焦尔当天在核电站现场表示，3号机组的6号汽轮机已重新联网恢复发电。本月早些时候，干旱引发的多瑙河极低水位严重限制冷却水吸入，导致部分机组被迫停运。 为保障冷却水供应，匈牙利政府日前实施紧急应对措施，开始建造水下潜坝，并在河道中有控制地沉入两艘80米长的驳船。毛焦尔表示，这些措施已使核电站附近多瑙河水位抬升约15厘米。 此前，持续酷暑和旱情导致多…"
