    "content": "中新网北京8月23日电(记者 周昕 李京泽) 应中国教育国际交流协会邀请，支持中国治沙事业的美国友人“赛考斯”(本名罗纳德·萨科尔斯基)23日凌晨抵达北京。时隔20余年再度来到中国，“赛考斯”用中文说出“我回来了”。他告诉记者，“当飞机着陆时，我意识到，我回到了我的第二个家，我将看到我的‘家人’”。"
