    "description": "中新网北京8月23日电(记者 周昕 李京泽) 8月23日凌晨，应中国教育国际交流协会邀请，支持中国治沙事业的美国友人“赛考斯”(本名罗纳德·萨科尔斯基)抵达北京。在机场接受记者采访时，“赛考斯”表示，自己与殷玉珍的缘分是一段由上天书写的故事。“我只是扮演好自己的角色，殷玉珍才是真正的英雄。这是故事的一个篇章。我即将要去的那片森林，将会是全新的篇章。”",
    "content": "中新网北京8月23日电(记者 周昕 李京泽) 8月23日凌晨，应中国教育国际交流协会邀请，支持中国治沙事业的美国友人“赛考斯”(本名罗纳德·萨科尔斯基)抵达北京。在机场接受记者采访时，“赛考斯”表示，自己与殷玉珍的缘分是一段由上天书写的故事。“我只是扮演好自己的角色，殷玉珍才是真正的英雄。这是故事的一个篇章。我即将要去的那片森林，将会是全新的篇章。”"
