    "content": "新华社里加8月22日电（记者陈玉芬）拉脱维亚22日晚间遭遇强风暴，大量树木或树枝被折断，配电网络遭到严重破坏，全国超过18万用户停电。 此次强气旋从南部进入拉脱维亚，同时带来暴雨和破坏性大风。拉脱维亚通讯社将其称为2005年1月以来破坏性最强风暴。当天拉脱维亚中部一些地方的降水量已经达到当地月降水量的大约一半。 拉脱维亚环境、地质和气象中心22日对中部和西部地区持续发出强降雨红色预警，与此同时，强阵风的橙色预警几乎覆盖全国。 拉脱维亚铁路运营部门说，由于天气原因，22日晚多趟列车运行出现延误。 拉脱维亚电力公司的数…"
