    "content": "新华社东京8月23日电（记者李子越 陈泽安）日本茨城县南部23日凌晨发生5.9级地震，位于震中附近的多处核设施暂未发现异常。 日本广播协会引述电力公司方面消息称，地震发生后，位于震中附近的福岛第一和第二核电站、东海核电站和东海第二核电站目前暂未发现异常，核电站周边辐射监测点的数值也未发生明显变化。 此次地震，日本茨城县、东京都、埼玉县和千叶县部分地区观测到震度5弱的摇晃。日本气象厅设定的地震震度由弱到强分别为0至4、5弱、5强、6弱、6强和7，共10个等级。日本气象厅称，震度5弱的摇晃可能导致架子上的餐具、书籍等物…"
