    "content": "新华社索非亚8月22日电（记者周海伦）保加利亚国防部长迪米特尔·斯托扬诺夫22日表示，两架美国军机已离开保加利亚贝兹梅尔空军基地，早于其获准的停留期限。 斯托扬诺夫说，美军飞机在贝兹梅尔空军基地停留期间，没有进行过一次南下飞行；所有飞行均在西部和西北部的盟国领空进行训练，保加利亚“没有收到任何有关国家安全受到直接威胁的信息”。 保加利亚总统约托娃当天在出席活动时也向媒体证实，这些飞机已离开空军基地，任务已经结束。 据保加利亚当地媒体此前援引国防部消息，在贝兹梅尔空军基地部署的美军飞机仅有两架，于7月31日抵达。 7…"
