    "content": "新华社安卡拉8月22日电（记者王腾飞）据土耳其伊赫拉斯通讯社22日报道，一艘由土耳其航运公司运营的商船当天凌晨在俄罗斯黑海港口新罗西斯克附近海域遭袭，造成1名船员死亡、8人受伤。 报道称，遇袭商船名为“乌拉尔”号。该商船遇袭后继续航行，目前已经抵达土耳其北部港口萨姆松。 另据“今日土耳其”网站报道，此前另一艘土耳其籍货船“内吉贝”号在黑海上遇袭后，船上18名船员被转移至“乌拉尔”号上。“内吉贝”号和“乌拉尔”号均遭到无人机袭击。 英国媒体称，今年7月黑海地区有超过35艘商船遭到袭击，造成23名海员死亡。进入8月，黑…"
