    "content": "新华社曼谷8月23日电（记者林淑婷 常天童）泰国第四军区22日晚在社交媒体平台上发布警告称，当晚泰国南部发生多起恶性事件，当局正在调查，请民众保持警惕。 据泰媒报道，泰国南部三府那拉提瓦、也拉和北大年当晚相继发生爆炸、纵火等恶性事件，已造成至少两人受伤。袭击包括纵火焚烧汽车轮胎和乡镇行政办公室、炸毁电线杆和便利店等。那拉提瓦府发生至少11起恶性事件，其中一起汽车爆炸造成两人受伤。 隶属军方的特遣部队通过社交媒体宣布，那拉提瓦全府从22日22时15分起宵禁至23日6时。居民如确有紧急事由，出行前须取得当地军警或行政人…"
