    "description": "新华社伦敦8月22日电（记者张枫）据英国警方22日通报，当天凌晨在克利夫兰郡发生一起交通事故，造成7人死亡。 通报说，一辆逆向行驶的汽车与一辆正常行驶的警车相撞，车上所有人员当场死亡，包括逆行汽车上的5人和警车上的两名警员。 英国首相伯纳姆当天在社交媒体发文说，对两名执勤警员和另外5人的死亡“深感悲痛”。",
