    "content": "新华社莫斯科8月22日电（记者赵冰）据俄罗斯媒体22日报道，普京在当天播出的一段视频采访中表示，为回应乌克兰武装部队对俄民用目标的袭击，俄军已加大对乌方企业的打击力度。 普京说，乌克兰武装部队在过去40天里持续使用导弹和无人机对俄罗斯民用和物流设施发动攻击，这是乌克兰及其背后西方支持者的“又一场冒险”，目标是让俄罗斯遭遇战略性失败。他表示，上述攻击并未达到乌克兰的预期目标，“只是造成了一些经济损失”。 普京说，乌方想要破坏俄经济，于是“打开潘多拉魔盒”，俄方予以报复性打击。 普京表示，乌军的行动并未对前线局势造成任…"
