    "description": "新华社东京8月23日电（记者李子越 陈泽安）日本茨城县南部23日凌晨发生5.9级地震，东京震感明显。 日本气象厅说，地震发生在当地时间23日2时0分（北京时间23日1时0分）左右，震中位于北纬36.0度、东经140.1度，震级为5.9级，震源深度约70公里。气象厅说无需担心此次地震会引发海啸。",
